import csv
from pathlib import Path
p=Path(__file__).parent
def add(file,rows,keys):
    f=p/file
    with f.open(encoding='utf-8-sig',newline='') as x:
        r=csv.DictReader(x); fs=r.fieldnames; old=list(r)
    seen={tuple(y.get(k,'') for k in keys) for y in old}
    for row in rows:
        key=tuple(row.get(k,'') for k in keys)
        if key not in seen: old.append({k:row.get(k,'') for k in fs});seen.add(key)
    with f.open('w',encoding='utf-8-sig',newline='') as x:
        w=csv.DictWriter(x,fieldnames=fs);w.writeheader();w.writerows(old)
